CREATE TABLE IF NOT EXISTS customer_activities(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),activity_type TEXT NOT NULL CHECK(activity_type IN ('project','support','contract','quotation','opportunity')),title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',reference TEXT,owner_id TEXT REFERENCES users(id),due_date TEXT,notes TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_customer_activities_customer ON customer_activities(customer_id,activity_type);
